import type { ServerResponse } from "node:http";

import { StorageError } from "../../storage/errors.js";
import {
  CreateSessionRootPolicy,
  ListSessionDirectory,
  ReadSessionFile,
} from "../files/sessionBrowser.js";
import { SendJson } from "../http.js";
import type { RouteContext } from "./context.js";

export async function HandleGetSessionFile(
  context: RouteContext,
  pile: string,
  sessionId: string,
  pathParam: string | null,
  response: ServerResponse,
): Promise<void>
{
  if (pathParam === null || pathParam.trim().length === 0)
  {
    throw new StorageError("invalid_request", "path query parameter is required");
  }

  const policy = await CreateSessionRootPolicy(context.agentManager, pile, sessionId);
  const result = await ReadSessionFile(policy, pathParam);
  SendJson(response, 200, result);
}

export async function HandleListSessionFiles(
  context: RouteContext,
  pile: string,
  sessionId: string,
  pathParam: string | null,
  response: ServerResponse,
): Promise<void>
{
  const policy = await CreateSessionRootPolicy(context.agentManager, pile, sessionId);
  const relativePath = pathParam ?? ".";
  const result = await ListSessionDirectory(policy, relativePath);
  SendJson(response, 200, result);
}

import type { ServerResponse } from "node:http";

import { AgentManagerError } from "../agents/manager.js";
import { ModelValidationError } from "../agents/models.js";
import { FormatRestError } from "../shared/errors.js";
import { StorageError } from "../storage/errors.js";
import { SendJson } from "./http.js";

const x_errorStatusCodes: Record<string, number> = {
  invalid_request: 400,
  invalid_json: 400,
  invalid_pile: 400,
  invalid_session_id: 400,
  invalid_name: 400,
  invalid_manifest: 400,
  invalid_history_request: 400,
  invalid_sequence: 400,
  model_unavailable: 400,
  invalid_root_directory: 400,
  method_not_allowed: 405,
  not_found: 404,
  pile_not_found: 404,
  manifest_not_found: 404,
  model_not_found: 404,
  session_not_found: 404,
  file_not_found: 404,
  path_escape: 403,
  unsupported_file: 400,
  not_a_file: 400,
  not_a_directory: 400,
};

export function ResolveErrorStatusCode(code: string): number
{
  return x_errorStatusCodes[code] ?? 500;
}

export function SendRestError(
  response: ServerResponse,
  statusCode: number,
  code: string,
  message: string,
): void
{
  SendJson(response, statusCode, FormatRestError(code, message));
}

export function HandleRouteError(response: ServerResponse, error: unknown): void
{
  if (error instanceof StorageError)
  {
    SendRestError(
      response,
      ResolveErrorStatusCode(error.code),
      error.code,
      error.message,
    );
    return;
  }

  if (error instanceof ModelValidationError)
  {
    SendRestError(
      response,
      ResolveErrorStatusCode(error.code),
      error.code,
      error.message,
    );
    return;
  }

  if (error instanceof AgentManagerError)
  {
    SendRestError(
      response,
      ResolveErrorStatusCode(error.code),
      error.code,
      error.message,
    );
    return;

import type { IncomingMessage, ServerResponse } from "node:http";

import { StorageError } from "../storage/errors.js";
import { HandleRouteError, SendRestError } from "./errors.js";
import { HandleHealth } from "./routes/health.js";
import { HandleGetSessionFile, HandleListSessionFiles } from "./routes/files.js";
import { HandleSessionHistory } from "./routes/history.js";
import { HandleListModels } from "./routes/models.js";
import { HandleCreatePile, HandleListPiles } from "./routes/piles.js";
import {
  HandleCreateSession,
  HandleGetSession,
  HandleListSessions,
} from "./routes/sessions.js";
import type { RouteContext } from "./routes/context.js";

export interface MatchedRoute
{
  pile?: string;
  sessionId?: string;
  history?: boolean;
  file?: boolean;
  files?: boolean;
}

function DecodePathSegment(segment: string): string
{
  try
  {
    return decodeURIComponent(segment);
  }
  catch
  {
    throw new StorageError("invalid_request", "route path is not valid");
  }
}

export function MatchApiRoute(pathname: string): MatchedRoute | null
{
  const segments = pathname.split("/").filter((segment) => segment.length > 0);

  if (segments.length < 2 || segments[0] !== "api")
  {
    return null;
  }

  if (segments.length === 2)
  {
    if (segments[1] === "health" || segments[1] === "models")
    {
      return {};
    }

    if (segments[1] === "piles")
    {
      return {};
    }

    return null;
  }

  if (segments[1] !== "piles" || segments.length < 3)
  {
    return null;
  }

  const pile = DecodePathSegment(segments[2]);

  if (segments.length === 3)
  {
    return { pile };
  }

  if (segments[3] !== "sessions")
  {
    return null;
  }

  if (segments.length === 4)
  {
    return { pile };
  }

  const sessionId = DecodePathSegment(segments[4]);

  if (segments.length === 5)
  {
    return { pile, sessionId };
  }

  if (segments.length === 6)
  {
    if (segments[5] === "history")
    {
      return { pile, sessionId, history: true };
    }

    if (segments[5] === "file")
    {
      return { pile, sessionId, file: true };
    }

    if (segments[5] === "files")
    {
      return { pile, sessionId, files: true };
    }
  }

  return null;
}

export function ResolveApiEndpoint(pathname: string): string | null
{
  const segments = pathname.split("/").filter((segment) => segment.length > 0);

  if (segments.length < 2 || segments[0] !== "api")
  {
    return null;
  }

  if (segments.length === 2)
  {
    return segments[1] ?? null;
  }

  if (segments[1] === "piles")
  {
    if (segments[3] === "sessions")
    {
      if (segments.length === 4)
      {
        return "pile_sessions";
      }

      if (segments.length === 5)
      {
        return "pile_session";
      }

      if (segments.length === 6)
      {
        if (segments[5] === "history")
        {
          return "pile_session_history";
        }

        if (segments[5] === "file")
        {
          return "pile_session_file";
        }

        if (segments[5] === "files")
        {
          return "pile_session_files";
        }
      }
    }
  }

  return null;
}

export async function DispatchApiRoute(
  context: RouteContext,
  request: IncomingMessage,
  response: ServerResponse,
  url: URL,
): Promise<void>
{
  const endpoint = ResolveApiEndpoint(url.pathname);

  if (endpoint === null)
  {
    SendRestError(response, 404, "not_found", "route not found");
    return;
  }

  const route = MatchApiRoute(url.pathname);

  if (route === null)
  {
    SendRestError(response, 404, "not_found", "route not found");
    return;
  }

  try
  {
    if (endpoint === "health")
    {
      if (request.method !== "GET")
      {
        SendRestError(response, 405, "method_not_allowed", "method not allowed");
        return;
      }

      HandleHealth(context, response);
      return;
    }

    if (endpoint === "models")
    {
      if (request.method !== "GET")
      {
        SendRestError(response, 405, "method_not_allowed", "method not allowed");
        return;
      }

      HandleListModels(context, response);
      return;
    }

    if (endpoint === "piles")
    {
      if (request.method === "GET")
      {
        await HandleListPiles(context, response);
        return;
      }

      if (request.method === "POST")
      {
        await HandleCreatePile(context, request, response);
        return;
      }

      SendRestError(response, 405, "method_not_allowed", "method not allowed");
      return;
    }

    if (endpoint === "pile_sessions")
    {
      if (route.pile === undefined)
      {
        SendRestError(response, 404, "not_found", "route not found");
        return;
      }

      if (request.method === "GET")
      {
        await HandleListSessions(context, route.pile, response);
        return;
      }

      if (request.method === "POST")
      {
        await HandleCreateSession(context, route.pile, request, response);
        return;
      }

      SendRestError(response, 405, "method_not_allowed", "method not allowed");
      return;
    }

    if (endpoint === "pile_session")
    {
      if (route.pile === undefined || route.sessionId === undefined)
      {
        SendRestError(response, 404, "not_found", "route not found");
        return;
      }

      if (request.method !== "GET")
      {
        SendRestError(response, 405, "method_not_allowed", "method not allowed");
        return;
      }

      await HandleGetSession(context, route.pile, route.sessionId, response);
      return;
    }

    if (endpoint === "pile_session_history")
    {
      if (route.pile === undefined || route.sessionId === undefined)
      {
        SendRestError(response, 404, "not_found", "route not found");
        return;
      }

      if (request.method !== "GET")
      {
        SendRestError(response, 405, "method_not_allowed", "method not allowed");
        return;
      }

      await HandleSessionHistory(
        context,
        route.pile,
        route.sessionId,
        url.searchParams,
        response,
      );
      return;
    }

    if (endpoint === "pile_session_file")
    {
      if (route.pile === undefined || route.sessionId === undefined)
      {
        SendRestError(response, 404, "not_found", "route not found");
        return;
      }

      if (request.method !== "GET")
      {
        SendRestError(response, 405, "method_not_allowed", "method not allowed");
        return;
      }

      await HandleGetSessionFile(
        context,
        route.pile,
        route.sessionId,
        url.searchParams.get("path"),
        response,
      );
      return;
    }

    if (endpoint === "pile_session_files")
    {
      if (route.pile === undefined || route.sessionId === undefined)
      {
        SendRestError(response, 404, "not_found", "route not found");
        return;
      }

      if (request.method !== "GET")
      {
        SendRestError(response, 405, "method_not_allowed", "method not allowed");
        return;
      }

      await HandleListSessionFiles(
        context,
        route.pile,
        route.sessionId,
        url.searchParams.get("path"),
        response,
      );
      return;
    }

    SendRestError(response, 404, "not_found", "route not found");
  }
  catch (error)
  {
    HandleRouteError(response, error);
  }
}

import { constants } from "node:fs";
import { access, lstat, readdir, readFile, realpath, stat } from "node:fs/promises";
import path from "node:path";

import type { AgentManager } from "../../agents/manager.js";
import { PathEscapeError } from "../../extensions/sheaf-chat/errors.js";
import {
  ClassifyDirectoryEntry,
  ClassifyFile,
} from "../../extensions/sheaf-chat/fileClassification.js";
import {
  CreateRootPolicy,
  type RootPolicy,
} from "../../extensions/sheaf-chat/pathPolicy.js";
import { x_treeDefaultIgnores } from "../../extensions/sheaf-chat/toolHelpers.js";
import { StorageError } from "../../storage/errors.js";

export interface FileBrowserEntry
{
  name: string;
  path: string;
  kind: "file" | "directory";
  supported?: boolean;
  contentType?: string;
}

export interface FileGetResponse
{
  file: FileBrowserEntry & {
    content: string;
    size: number;
    modifiedAt: string;
  };
}

export interface FileListResponse
{
  directory: FileBrowserEntry;
  entries: FileBrowserEntry[];
}

export interface ResolveBrowserRelativePathOptions
{
  allowEmpty?: boolean;
}

function NormalizeSeparators(inputPath: string): string
{
  return inputPath.replace(/\\/g, "/");
}

function HasParentTraversal(inputPath: string): boolean
{
  const segments = NormalizeSeparators(inputPath).split("/");

  for (const segment of segments)
  {
    if (segment === "..")
    {
      return true;
    }
  }

  return false;
}

function RejectBrowserAbsolutePath(inputPath: string): void
{
  const normalized = NormalizeSeparators(inputPath.trim());

  if (path.isAbsolute(normalized) || /^[a-zA-Z]:/.test(normalized))
  {
    throw new StorageError("path_escape", "path must be relative to the session root");
  }
}

function MapPathEscapeError(error: unknown): never
{
  if (error instanceof PathEscapeError)
  {
    throw new StorageError("path_escape", error.message);
  }

  throw error;
}

function IsMissingPathError(error: unknown): boolean
{
  if (!(error instanceof Error))
  {
    return false;
  }

  const errnoCode = (error as NodeJS.ErrnoException).code;

  return errnoCode === "ENOENT" || errnoCode === "ENOTDIR";
}

async function ResolveBrowserExistingPath(
  policy: RootPolicy,
  relativePath: string,
  options?: ResolveBrowserRelativePathOptions,
): Promise<string>
{
  try
  {
    return await ResolveBrowserRelativePath(policy, relativePath, options);
  }
  catch (error)
  {
    if (error instanceof StorageError)
    {
      throw error;
    }

    if (IsMissingPathError(error))
    {
      throw new StorageError("file_not_found", "path not found");
    }

    MapPathEscapeError(error);
  }
}

export async function CreateSessionRootPolicy(
  agentManager: AgentManager,
  pile: string,
  sessionId: string,
): Promise<RootPolicy>
{
  const rootDirectory = await agentManager.resolveSessionRootDirectory(pile, sessionId);
  return CreateRootPolicy(rootDirectory);
}

export async function ResolveBrowserRelativePath(
  policy: RootPolicy,
  relativePath: string,
  options?: ResolveBrowserRelativePathOptions,
): Promise<string>
{
  if (relativePath.includes("\0"))
  {
    throw new StorageError("path_escape", "path must be relative to the session root");
  }

  const trimmed = relativePath.trim();

  if (trimmed.length === 0)
  {
    if (options?.allowEmpty)
    {
      try
      {
        return await policy.ResolveInputPath(".");
      }
      catch (error)
      {
        MapPathEscapeError(error);
      }
    }

    throw new StorageError("invalid_request", "path query parameter is required");
  }

  RejectBrowserAbsolutePath(trimmed);

  if (HasParentTraversal(trimmed))
  {
    throw new StorageError("path_escape", "path must be relative to the session root");
  }

  try
  {
    return await policy.ResolveInputPath(NormalizeSeparators(trimmed));
  }
  catch (error)
  {
    MapPathEscapeError(error);
  }
}

function ShouldIgnoreDirectory(name: string): boolean
{
  return x_treeDefaultIgnores.includes(name);
}

function BuildDirectoryEntry(policy: RootPolicy, absolutePath: string): FileBrowserEntry
{
  const relativePath = policy.ToRootRelativePath(absolutePath);

  return {
    name: path.basename(absolutePath),
    path: relativePath === "." ? "." : relativePath,
    kind: "directory",
    supported: true,
  };
}

function SortBrowserEntries(left: FileBrowserEntry, right: FileBrowserEntry): number
{
  if (left.kind !== right.kind)
  {
    return left.kind === "directory" ? -1 : 1;
  }

  return left.name.localeCompare(right.name);
}

export async function ReadSessionFile(
  policy: RootPolicy,
  relativePath: string,
): Promise<FileGetResponse>
{
  const absolutePath = await ResolveBrowserExistingPath(policy, relativePath);
  const fileStat = await stat(absolutePath);

  if (fileStat.isDirectory())
  {
    throw new StorageError("not_a_file", "path is a directory, not a file");
  }

  const buffer = await readFile(absolutePath);
  const classification = ClassifyFile(path.basename(absolutePath), buffer);

  if (!classification.supported)
  {
    throw new StorageError("unsupported_file", "file is not a supported text document");
  }

  const rootRelativePath = policy.ToRootRelativePath(absolutePath);

  return {
    file: {
      name: path.basename(absolutePath),
      path: rootRelativePath,
      kind: "file",
      supported: true,
      contentType: classification.contentType,
      content: buffer.toString("utf-8"),
      size: fileStat.size,
      modifiedAt: fileStat.mtime.toISOString(),
    },
  };
}

async function ResolveListableEntry(
  policy: RootPolicy,
  parentAbsolute: string,
  entryName: string,
): Promise<{ absolutePath: string; kind: "file" | "directory" } | null>
{
  const entryAbsolute = path.join(parentAbsolute, entryName);
  policy.AssertWithinRoot(entryAbsolute);

  const entryStat = await lstat(entryAbsolute);

  if (entryStat.isSymbolicLink())
  {
    try
    {
      const resolved = await realpath(entryAbsolute);
      policy.AssertWithinRoot(resolved);
      const resolvedStat = await stat(resolved);

      if (resolvedStat.isDirectory())
      {
        return { absolutePath: resolved, kind: "directory" };
      }

      return { absolutePath: resolved, kind: "file" };
    }
    catch
    {
      return null;
    }
  }

  if (entryStat.isDirectory())
  {
    return { absolutePath: entryAbsolute, kind: "directory" };
  }

  if (entryStat.isFile())
  {
    return { absolutePath: entryAbsolute, kind: "file" };
  }

  return null;
}

export async function ListSessionDirectory(
  policy: RootPolicy,
  relativePath: string,
): Promise<FileListResponse>
{
  const absolutePath = await ResolveBrowserExistingPath(policy, relativePath, {
    allowEmpty: true,
  });
  const directoryStat = await stat(absolutePath);

  if (!directoryStat.isDirectory())
  {
    throw new StorageError("not_a_directory", "path is not a directory");
  }

  const directory = BuildDirectoryEntry(policy, absolutePath);
  const dirEntries = await readdir(absolutePath);
  const entries: FileBrowserEntry[] = [];

  for (const entryName of dirEntries)
  {
    const resolved = await ResolveListableEntry(policy, absolutePath, entryName);

    if (resolved === null)
    {
      continue;
    }

    const entryAbsolute = path.join(absolutePath, entryName);
    const rootRelativePath = policy.ToRootRelativePath(entryAbsolute);

    if (resolved.kind === "directory")
    {
      if (ShouldIgnoreDirectory(entryName))
      {
        continue;
      }

      entries.push({
        name: entryName,
        path: rootRelativePath,
        kind: "directory",
        supported: true,
      });
      continue;
    }

    const classification = ClassifyDirectoryEntry(entryName);

    entries.push({
      name: entryName,
      path: rootRelativePath,
      kind: "file",
      supported: classification.supported,
      ...(classification.contentType !== undefined
        ? { contentType: classification.contentType }
        : {}),
    });
  }

  entries.sort(SortBrowserEntries);

  return {
    directory,
    entries,
  };
}

