  "use strict";

  const x_MarkdownExtensions = [".md", ".markdown"];
  const x_SheafFilePrefix = "sheaf-file:";
  const x_MathPlaceholderPrefix = "[[[SHEAF_MATH_";
  const x_MathPlaceholderSuffix = "]]]";

